import * as React from "react";
import { cx } from "./cx";

export interface ToggleProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "onChange"> {
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
}

/** Press switch; state lives in aria-pressed. */
export const Toggle = React.forwardRef<HTMLButtonElement, ToggleProps>(function Toggle(
  { pressed, defaultPressed, onPressedChange, className, onClick, ...props },
  ref,
) {
  const [inner, setInner] = React.useState(defaultPressed ?? false);
  const isControlled = pressed !== undefined;
  const on = isControlled ? pressed : inner;
  return (
    <button
      ref={ref}
      type="button"
      aria-pressed={on}
      className={cx("rs-toggle", className)}
      onClick={(e) => {
        if (!isControlled) setInner(!on);
        onPressedChange?.(!on);
        onClick?.(e);
      }}
      {...props}
    />
  );
});

export interface ToggleGroupProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  options: Array<{ value: string; label: React.ReactNode }>;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

/** One pressed at a time. */
export function ToggleGroup({
  options,
  value,
  defaultValue,
  onValueChange,
  className,
  ...props
}: ToggleGroupProps) {
  const [inner, setInner] = React.useState(defaultValue);
  const isControlled = value !== undefined;
  const current = isControlled ? value : inner;
  return (
    <div role="group" className={cx("rs-toggle-group", className)} {...props}>
      {options.map((option) => (
        <button
          key={option.value}
          type="button"
          aria-pressed={option.value === current}
          className="rs-toggle"
          onClick={() => {
            if (!isControlled) setInner(option.value);
            onValueChange?.(option.value);
          }}
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Toggle: a press switch; on is ink, like everything on ── */
.rs-toggle{display:inline-flex;align-items:center;justify-content:center;height:32px;min-width:32px;padding:0 10px;font-size:13px;font-weight:500;letter-spacing:-.01em;background:none;border:1px solid var(--divider);border-radius:var(--radius-sm);color:var(--text-secondary);cursor:pointer;font-family:inherit;transition:background-color var(--duration-snap) var(--ease),color var(--duration-snap) var(--ease),border-color var(--duration-snap) var(--ease)}
.rs-toggle[aria-pressed="true"]{background:var(--text);border-color:var(--text);color:var(--bg)}
.rs-toggle-group{display:inline-flex}
.rs-toggle-group .rs-toggle{border-radius:0;margin-left:-1px}
.rs-toggle-group .rs-toggle:first-child{border-radius:var(--radius-sm) 0 0 var(--radius-sm);margin-left:0}
.rs-toggle-group .rs-toggle:last-child{border-radius:0 var(--radius-sm) var(--radius-sm) 0}
.rs-toggle-group .rs-toggle[aria-pressed="true"]{position:relative;z-index:1}
